using System.Globalization;
using Jint;
using Jint.Native;
using Jint.Native.Json;
using Jint.Native.Object;
using Jint.Runtime;
using TreeSpitter.Grammars;

namespace TreeSpitter.Dsl;

/// <summary>
/// Converts the JavaScript objects created by the tree-sitter DSL, or parsed from a <c>grammar.json</c> file, to a
/// <see cref="Grammar"/>.
/// </summary>
public static class GrammarConverter
{
    /// <summary>Reads a <c>grammar.json</c> file, as generated by <c>tree-sitter generate</c>.</summary>
    public static Grammar FromJson(string json)
    {
        if (json is null)
        {
            throw new ArgumentNullException(nameof(json));
        }

        var engine = new Engine();
        var value = new JsonParser(engine).Parse(json);
        return FromGrammarObject(value);
    }

    /// <summary>Reads a <c>grammar.json</c> file, as generated by <c>tree-sitter generate</c>.</summary>
    public static Grammar FromJsonFile(string path) => FromJson(System.IO.File.ReadAllText(path));

    /// <summary>
    /// Converts the value exported by a grammar module: the result of <c>grammar(...)</c>, which has a <c>grammar</c>
    /// property, or the grammar object itself.
    /// </summary>
    public static Grammar FromEvaluationResult(JsValue exported)
    {
        if (!exported.IsObject())
        {
            throw new GrammarEvaluationException("The grammar module must export the result of the grammar() function.");
        }

        var grammar = exported.AsObject().Get("grammar");
        if (grammar.IsObject() && !grammar.AsObject().Get("rules").IsUndefined())
        {
            return FromGrammarObject(grammar);
        }

        if (!exported.AsObject().Get("rules").IsUndefined())
        {
            return FromGrammarObject(exported);
        }

        throw new GrammarEvaluationException("The grammar module must export the result of the grammar() function.");
    }

    /// <summary>Converts an object with the shape of a <c>grammar.json</c> file.</summary>
    public static Grammar FromGrammarObject(JsValue value)
    {
        var grammar = AsObject(value, "grammar");

        var rules = new List<GrammarRule>();
        var rulesObject = AsObject(grammar.Get("rules"), "rules");
        foreach (var key in rulesObject.GetOwnPropertyKeys(Types.String))
        {
            var name = key.ToString();
            rules.Add(new GrammarRule(name, ToRule(rulesObject.Get(key), name)));
        }

        var reserved = new List<ReservedWordSet>();
        if (grammar.Get("reserved") is { } reservedValue && reservedValue.IsObject())
        {
            var reservedObject = reservedValue.AsObject();
            foreach (var key in reservedObject.GetOwnPropertyKeys(Types.String))
            {
                var name = key.ToString();
                reserved.Add(new ReservedWordSet(name, ToRules(reservedObject.Get(key), "reserved." + name)));
            }
        }

        var precedences = new List<IReadOnlyList<Rule>>();
        foreach (var list in Items(grammar.Get("precedences")))
        {
            precedences.Add(ToRules(list, "precedences"));
        }

        var conflicts = new List<IReadOnlyList<string>>();
        foreach (var list in Items(grammar.Get("conflicts")))
        {
            conflicts.Add(ToStrings(list, "conflicts"));
        }

        return new Grammar
        {
            Name = ToStringValue(grammar.Get("name"), "name") ?? throw new GrammarEvaluationException("The grammar has no name."),
            Inherits = ToStringValue(grammar.Get("inherits"), "inherits"),
            Word = ToStringValue(grammar.Get("word"), "word"),
            Rules = rules,
            Extras = grammar.Get("extras").IsUndefined() ? [new PatternRule("\\s")] : ToRules(grammar.Get("extras"), "extras"),
            Conflicts = conflicts,
            Precedences = precedences,
            Externals = ToRules(grammar.Get("externals"), "externals"),
            Inline = ToStrings(grammar.Get("inline"), "inline"),
            Supertypes = ToStrings(grammar.Get("supertypes"), "supertypes"),
            Reserved = reserved,
        };
    }

    private static Rule ToRule(JsValue value, string context)
    {
        var rule = AsObject(value, context);
        var type = ToStringValue(rule.Get("type"), context + ".type")
            ?? throw new GrammarEvaluationException($"Invalid rule in '{context}': the 'type' property is missing.");

        return type switch
        {
            "BLANK" => BlankRule.Instance,
            "EOF" => EofRule.Instance,
            "STRING" => new StringRule(RequiredString(rule, "value", context)),
            "PATTERN" => new PatternRule(RequiredString(rule, "value", context), ToStringValue(rule.Get("flags"), context) ?? string.Empty),
            "SYMBOL" => new SymbolRule(RequiredString(rule, "name", context)),
            "SEQ" => new SeqRule(ToRules(rule.Get("members"), context)),
            "CHOICE" => new ChoiceRule(ToRules(rule.Get("members"), context)),
            "REPEAT" => new RepeatRule(ToRule(rule.Get("content"), context)),
            "REPEAT1" => new Repeat1Rule(ToRule(rule.Get("content"), context)),
            "PREC" => new PrecRule(PrecedenceKind.Default, ToPrecedence(rule.Get("value"), context), ToRule(rule.Get("content"), context)),
            "PREC_LEFT" => new PrecRule(PrecedenceKind.Left, ToPrecedence(rule.Get("value"), context), ToRule(rule.Get("content"), context)),
            "PREC_RIGHT" => new PrecRule(PrecedenceKind.Right, ToPrecedence(rule.Get("value"), context), ToRule(rule.Get("content"), context)),
            "PREC_DYNAMIC" => new PrecRule(PrecedenceKind.Dynamic, ToPrecedence(rule.Get("value"), context), ToRule(rule.Get("content"), context)),
            "TOKEN" => new TokenRule(ToRule(rule.Get("content"), context)),
            "IMMEDIATE_TOKEN" => new TokenRule(ToRule(rule.Get("content"), context), Immediate: true),
            "ALIAS" => new AliasRule(ToRule(rule.Get("content"), context), RequiredString(rule, "value", context), rule.Get("named").IsBoolean() && rule.Get("named").AsBoolean()),
            "FIELD" => new FieldRule(RequiredString(rule, "name", context), ToRule(rule.Get("content"), context)),
            "RESERVED" => new ReservedRule(RequiredString(rule, "context_name", context), ToRule(rule.Get("content"), context)),
            _ => throw new GrammarEvaluationException($"Unknown rule type '{type}' in '{context}'."),
        };
    }

    private static PrecedenceValue ToPrecedence(JsValue value, string context)
    {
        if (value.IsNumber())
        {
            var number = value.AsNumber();
            return new PrecedenceValue(checked((int)number));
        }

        if (value.IsString())
        {
            return new PrecedenceValue(value.AsString());
        }

        throw new GrammarEvaluationException($"Invalid precedence value '{value}' in '{context}'.");
    }

    private static IReadOnlyList<Rule> ToRules(JsValue value, string context)
    {
        var rules = new List<Rule>();
        foreach (var item in Items(value))
        {
            rules.Add(ToRule(item, context));
        }

        return rules;
    }

    private static IReadOnlyList<string> ToStrings(JsValue value, string context)
    {
        var strings = new List<string>();
        foreach (var item in Items(value))
        {
            strings.Add(ToStringValue(item, context) ?? throw new GrammarEvaluationException($"Invalid value in '{context}'."));
        }

        return strings;
    }

    private static IEnumerable<JsValue> Items(JsValue value)
    {
        if (value.IsUndefined() || value.IsNull())
        {
            yield break;
        }

        if (!value.IsArray())
        {
            throw new GrammarEvaluationException($"Expected an array, got '{value}'.");
        }

        var array = value.AsArray();
        var length = (uint)array.Length;
        for (uint i = 0; i < length; i++)
        {
            yield return array.Get(i.ToString(CultureInfo.InvariantCulture));
        }
    }

    private static ObjectInstance AsObject(JsValue value, string context)
    {
        if (!value.IsObject())
        {
            throw new GrammarEvaluationException($"Invalid value in '{context}': expected an object, got '{value}'.");
        }

        return value.AsObject();
    }

    private static string RequiredString(ObjectInstance rule, string property, string context)
        => ToStringValue(rule.Get(property), context)
           ?? throw new GrammarEvaluationException($"Invalid rule in '{context}': the '{property}' property is missing.");

    private static string? ToStringValue(JsValue value, string context)
    {
        if (value.IsUndefined() || value.IsNull())
        {
            return null;
        }

        if (value.IsString())
        {
            return value.AsString();
        }

        throw new GrammarEvaluationException($"Invalid value in '{context}': expected a string, got '{value}'.");
    }
}
